        for r, c in markers:
            old_pos = (r, c)
            output[r][c] = bg

            # Move toward separator
            if r < sep_row:
                new_r = r + 6
            else:
                new_r = r - 6

            # Clamp to bounds
            new_r = max(0, min(new_r, h - 1))

            if old_pos[0] != new_r:
                output[new_r][c] = marker_color

        # Fill row below separator with 8s
        for c in range(w):
            if sep_row + 1 < h:
                output[sep_row + 1][c] = 8

    elif sep_col is not None:
        # Vertical separator processing similar
        for r, c in markers:
            old_c = c
            output[r][c] = bg
            if c < sep_col:
                new_c = c + 6
            else:
                new_c = c - 6
            new_c = max(0, min(new_c, w - 1))
            output[r][new_c] = marker_color

        # Fill column 8s
        for r in range(h):
            if sep_col + 1 < w:
                output[r][sep_col + 1] = 8

    return output
